def add_attachments(doc, user_data):
    """Добавление приложений к договору"""
    # Приложение 1
    doc.add_page_break()
    app_title = doc.add_paragraph('Приложение №1')
    app_title.alignment = WD_ALIGN_PARAGRAPH.CENTER
