def show_random_review(message):
    """Show random approved review"""
    conn = get_pg_connection()
    if not conn:
        bot.edit_message_text(
            "❌ Ошибка подключения к базе данных. Попробуйте позже.",
            message.chat.id,
            message.message_id
        )
        return

    try:
        cursor = conn.cursor()

        cursor.execute('''
            SELECT l.name, r.service_type, r.rating, r.text, r.created_date
            FROM reviews r
            JOIN label l ON r.user_id = l.telegram_id
            WHERE r.status = %s
            ORDER BY RANDOM()
            LIMIT 1
        ''',
                       ("approved",))

        review = cursor.fetchone()

        if not review:
            review_text = "😔 Пока нет отзывов"
        else:
            artist_name, service_type, rating, text, date = review
            stars = "⭐️" * rating
            review_text = (
                f"🎵 Отзыв о {service_type}\n\n"
                f"👤 {artist_name}\n"
                f"{stars}\n"
                f"💭 {text}\n"
                f"📅 {date}"
            )

        markup = types.InlineKeyboardMarkup()
        markup.add(
            types.InlineKeyboardButton("🔄 Еще отзыв", callback_data="reviews_random"),
            types.InlineKeyboardButton("◀️ Назад", callback_data="reviews_back_main")
        )

        bot.edit_message_text(
            review_text,
            message.chat.id,
            message.message_id,
            reply_markup=markup
        )
    except Error as e:
        logger.error(f"PostgreSQL error in show_random_review: {e}")
        bot.edit_message_text(
            "❌ Произошла ошибка при получении случайного отзыва.",
            message.chat.id,
            message.message_id
        )
    finally:
        if conn:
            cursor.close()
            return_pg_connection(conn)


def show_category_reviews(message, category):
    """Show approved reviews for specific category"""
    conn = get_pg_connection()
    if not conn:
        bot.reply_to(message, "❌ Ошибка подключения к базе данных. Попробуйте позже.")
        return

    try:
        cursor = conn.cursor()
        cursor.execute('''
            SELECT l.name, r.rating, r.text, r.created_date
            FROM reviews r
            JOIN label l ON r.user_id = l.telegram_id
            WHERE r.service_type = %s AND r.status = %s
            ORDER BY r.created_date DESC
            LIMIT 5
        ''', (category, "approved"))

        reviews = cursor.fetchall()

        # Форматирование отзывов
        reviews_text = f"⭐️ Отзывы о {category}:\n\n"
        for name, rating, text, date in reviews:
            stars = "⭐️" * rating
            date_str = date.strftime('%d.%m.%Y')
            reviews_text += f"👤 {name}\n{stars}\n💬 {text}\n📅 {date_str}\n\n"

        # Создание клавиатуры
        markup = types.InlineKeyboardMarkup()
        markup.add(types.InlineKeyboardButton("◀️ Назад", callback_data="reviews_back"))

        bot.send_message(message.chat.id, reviews_text, reply_markup=markup)

    except Error as e:
        logger.error(f"Ошибка при получении отзывов: {e}")
        bot.reply_to(message, "❌ Произошла ошибка при загрузке отзывов.")
    finally:
        if conn:
            cursor.close()
            return_pg_connection(conn)


@bot.callback_query_handler(func=lambda call: LEGACY_REVIEWS_ENABLED and call.data.startswith(("approve_review_", "reject_review_")))
def handle_review_moderation(call):
    """Handle review approval/rejection"""
    action = "approve" if call.data.startswith("approve") else "reject"
    review_id = int(call.data.split("_")[2])

    conn = get_pg_connection()
    if not conn:
        bot.answer_callback_query(call.id, "❌ Database error", show_alert=True)
        return

    try:
        cursor = conn.cursor()

        if action == "approve":
            # Обновляем статус отзыва
            cursor.execute('''
                UPDATE reviews SET status = 'approved' WHERE id = %s
            ''', (review_id,))
            message = "✅ Отзыв одобрен и опубликован"
        else:
            # Удаляем отзыв
            cursor.execute('''
                DELETE FROM reviews WHERE id = %s
            ''', (review_id,))
            message = "❌ Отзыв отклонен и удален"

        conn.commit()

        # Обновляем сообщение у администратора
        try:
            bot.edit_message_text(
                f"{call.message.text}\n\n{message}",
                call.message.chat.id,
                call.message.message_id
            )
        except Exception as e:
            logger.error(f"Error editing message: {e}")

        bot.answer_callback_query(call.id, message)

    except Exception as e:
        logger.error(f"Error moderating review: {e}")
        bot.answer_callback_query(call.id, "❌ Error processing request", show_alert=True)
    finally:
        if conn:
            cursor.close()
            return_pg_connection(conn)


