# Обновите функцию save_review
def save_review(message):
    """Save review to database and notify admins"""
    text = message.text.strip()
    user_id = message.from_user.id

    if not hasattr(bot, 'review_category') or not hasattr(bot, 'review_rating'):
        bot.reply_to(message, "❌ Ошибка данных отзыва. Пожалуйста, начните процесс заново.")
        return

    if not text:
        bot.reply_to(message, "❌ Текст отзыва не может быть пустым. Пожалуйста, напишите ваш отзыв:")
        bot.register_next_step_handler(message, save_review)
        return

    conn = get_pg_connection()
    if not conn:
        bot.reply_to(message, "❌ Ошибка подключения к базе данных. Не удалось сохранить отзыв.")
        return

    try:
        cursor = conn.cursor()
        cursor.execute('''
            INSERT INTO reviews (user_id, service_type, rating, text, status, created_date)
            VALUES (%s, %s, %s, %s, %s, %s)
            RETURNING id
        ''', (
            user_id,
            bot.review_category,
            bot.review_rating,
            text,
            "pending",
            datetime.now()
        ))

        review_id = cursor.fetchone()[0]
        conn.commit()
        notify_admins_about_new_review(review_id)

        delattr(bot, 'review_category')
        delattr(bot, 'review_rating')

        bot.reply_to(
            message,
            "✅ Спасибо за ваш отзыв! Он будет опубликован после проверки модератором."
        )

    except Exception as e:
        logger.error(f"Error saving review: {e}")
        bot.reply_to(message, f"❌ Произошла ошибка при сохранении отзыва: {str(e)}")
    finally:
        if conn:
            cursor.close()
            return_pg_connection(conn)


@bot.callback_query_handler(
    func=lambda call: LEGACY_REVIEWS_ENABLED
    and (call.data.startswith("review_approve_") or call.data.startswith("review_reject_"))
)
def handle_review_moderation(call):
    """Handle review approval/rejection"""
    action, review_id = call.data.split("_")[1:]
    review_id = int(review_id)

    conn = get_pg_connection()
    if not conn:
        bot.answer_callback_query(
            call.id,
            "❌ Ошибка подключения к базе данных. Попробуйте позже.",
            show_alert=True
        )
        return

    try:
        cursor = conn.cursor()

        if action == "approve":
            cursor.execute('UPDATE reviews SET status = %s WHERE id = %s', ("approved", review_id))
            status_text = "✅ Отзыв одобрен"
        else:
            cursor.execute('DELETE FROM reviews WHERE id = %s', (review_id,))
            status_text = "❌ Отзыв отклонен"

        conn.commit()

        # Edit the original message to show the result
        try:
            bot.edit_message_text(
                f"{call.message.text}\n\n{status_text}",
                call.message.chat.id,
                call.message.message_id,
                reply_markup=None  # remove buttons
            )
        except Exception as e:
            logger.error(f"Could not edit message: {e}")

        bot.answer_callback_query(call.id, status_text)

    except Error as e:
        logger.error(f"PostgreSQL error in handle_review_moderation: {e}")
        bot.answer_callback_query(
            call.id,
            "❌ Произошла ошибка при модерации отзыва.",
            show_alert=True
        )
    finally:
        if conn:
            cursor.close()
            return_pg_connection(conn)


def check_pending_reviews():
    """Check and notify about pending reviews"""
    conn = get_pg_connection()
    if not conn:
        return

    try:
        cursor = conn.cursor()
        cursor.execute('SELECT COUNT(*) FROM reviews WHERE status = %s', ("pending",))
        count = cursor.fetchone()[0]

        if count > 0:
            # Получаем список админов
            cursor.execute('SELECT telegram_id FROM label WHERE admin = 1')
            admins = cursor.fetchall()

            for admin in admins:
                try:
                    bot.send_message(
                        admin[0],
                        f"🆕 Есть {count} отзывов на модерацию!\n"
                        "Используйте /admin -> Отзывы для просмотра"
                    )
                except Exception as e:
                    logger.error(f"Не удалось уведомить админа: {e}")

    except Error as e:
        logger.error(f"Ошибка проверки отзывов: {e}")
    finally:
        if conn:
            return_pg_connection(conn)


def get_display_username(user):
    if not user:
        return "Без имени"
    if isinstance(user, types.User):
        if user.username:
            return f"@{user.username}"
        return f"{user.first_name or user.id}"
    return str(user)


